'use strict';
const M=CourseModel;
const $=(s,el=document)=>el.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Zm2 10h3m4 0h3m-10 4h3',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',chart:'M4 3v18h17M8 16v-5m5 5V7m5 9V4',settings:'m9 3 1-1h4l1 3 3 1 3 2-1 3v2l1 3-3 2-3 1-1 3h-4l-1-3-3-1-3-2 1-3v-2L3 8l3-2 3-1zM12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',plus:'M12 5v14M5 12h14',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',check:'m5 12 4 4L19 6',save:'M5 3h12l4 4v14H3V3h2Zm2 0v6h10V3M7 21v-8h10v8',edit:'m15 4 5 5M4 20l5-1L21 7l-5-5L4 14v6Z',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',x:'m6 6 12 12M6 18 18 6',chevron:'m8 10 4 4 4-4',coffee:'M4 8h12v6a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5V8Zm12 0h2a3 3 0 0 1 0 6h-2M3 22h16M7 2v3m5-3v3',alert:'m12 3 10 18H2L12 3Zm0 6v5m0 3v1',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',book:'M3 3h7l2 2 2-2h7v17h-7l-2 2-2-2H3V3Zm9 2v17',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-4M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0m4-4a4 4 0 0 1 0 8',print:'M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6z',info:'M12 11v6m0-10v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',layers:'m12 2 10 6-10 6L2 8 12 2ZM2 12l10 6 10-6M2 16l10 6 10-6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.book}"/></svg>`;
const btn=(label,action,kind='',ic='',id='')=>`<button type="button" class="btn ${kind}" data-action="${action}"${id?` data-id="${esc(id)}"`:''}>${ic?icon(ic):''}${label}</button>`;
const iconButton=(name,action,id,label)=>`<button type="button" class="icon-btn" data-action="${action}" data-id="${esc(id)}" aria-label="${esc(label)}" title="${esc(label)}">${icon(name)}</button>`;
const tag=k=>`<span class="tag ${k.group==='Ja'?'self':k.group==='Drużyna'?'team':''}">${esc(k.name)}</span>`;
const fmt=n=>`${Math.floor(n/60)?Math.floor(n/60)+' h':''}${n%60?(n>=60?' ':'')+(n%60)+' min':n<60?'0 min':''}`;
const df=(d,opts)=>new Date(d+'T12:00:00').toLocaleDateString('pl-PL',opts);
const fullDate=d=>df(d,{weekday:'long',day:'numeric',month:'long',year:'numeric'});
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Warsaw',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let data,saveError='',protectStorage=false,pendingImport=null,competencyFilter='',groupFilter='Wszystkie',chartMode='minutes',comboMode='pairs',lastFocus=null,modalSubmit=null;
try{const raw=localStorage.getItem(M.KEY);data=raw?M.validate(JSON.parse(raw)):M.seed();if(!raw)localStorage.setItem(M.KEY,JSON.stringify(data));}catch(e){data=M.seed();protectStorage=true;saveError='Nie można odczytać lub zapisać danych przeglądarki. Poprzednie dane nie zostały nadpisane. Wyeksportuj bieżący kurs, aby zachować zmiany.';}
function course(){return data.course;}
function session(){return course().sessions.find(s=>s.id===data.ui.sessionId)||course().sessions[0];}
function day(){const s=session();return s?.days.find(d=>d.id===data.ui.dayId)||s?.days.slice().sort((a,b)=>a.date.localeCompare(b.date))[0];}
function syncSelection(){const s=session();data.ui.sessionId=s?.id||null;data.ui.dayId=day()?.id||null;}
function save(message){data.updatedAt=new Date().toISOString();if(!protectStorage){try{localStorage.setItem(M.KEY,JSON.stringify(data));saveError='';}catch(e){saveError='Nie udało się zapisać zmian w przeglądarce. Zmiany pozostają w tej karcie — wyeksportuj kurs do JSON.';}}if(message)toast(saveError?'Zmiana jest w tej karcie. Zapis lokalny wymaga uwagi.':message);}
let toastTimer;
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4500);}
function metric(label,value,foot,ic){return `<div class="metric"><div class="metric-label">${label}${icon(ic)}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`;}
function heading(title,sub,action='',eyebrow='Zarządzanie kursem'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtext">${sub}</p></div>${action}</div>`;}
function empty(title,copy,action='',ic='calendar'){return `<div class="empty"><div class="empty-icon">${icon(ic)}</div><h3>${title}</h3><p>${copy}</p>${action}</div>`;}
function render(){syncSelection();const names={schedule:'Harmonogram',competencies:'Kompetencje',analytics:'Analityka',settings:'Ustawienia'};const nav=[['schedule','calendar'],['competencies','grid'],['analytics','chart'],['settings','settings']];
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="logo-pzpn.png" alt="PZPN — Szkoła Trenerów im. Kazimierza Górskiego"><div class="brand-small">PLANER KURSÓW</div></div><div class="nav-caption">PRZESTRZEŃ KURSU</div><nav class="nav" aria-label="Główna nawigacja">${nav.map(([v,i])=>`<button data-action="view" data-id="${v}" class="${data.ui.view===v?'active':''}" ${data.ui.view===v?'aria-current="page"':''}>${icon(i)}<span>${names[v]}</span>${v==='competencies'?`<span class="count">${course().competencies.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-info"><strong>${icon('save')}Twój kurs, pod ręką</strong>Dane zapisują się automatycznie<br>w tej przeglądarce.</div><div class="profile"><div class="avatar">ST</div><div><strong>Organizator kursu</strong><span>Szkoła Trenerów</span></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><span>Moje kursy</span><span class="slash">/</span><strong>${esc(course().name)}</strong><span class="slash">/</span><span>${names[data.ui.view]}</span></div><div class="save-state ${saveError?'error':''}" title="${esc(saveError||'Zapis w pamięci tej przeglądarki')}">${icon(saveError?'alert':'check')}<span>${saveError?'Problem z zapisem':'Zapisano lokalnie'}</span></div></header>${saveError?`<div class="storage-warning" role="alert">${esc(saveError)}</div>`:''}<div class="content">${({schedule:renderSchedule,competencies:renderCompetencies,analytics:renderAnalytics,settings:renderSettings}[data.ui.view]||renderSchedule)()}</div></main></div>`;
 if(data.ui.view==='settings')bindImport();
}
function renderSchedule(){const c=course(),s=session(),d=day(),ls=M.lessons(c),allDays=c.sessions.reduce((n,s)=>n+s.days.length,0),total=ls.reduce((n,e)=>n+M.duration(e),0),tagged=ls.filter(e=>e.competencyIds.length).length;
 return heading('Harmonogram kursu','Zaplanuj zajęcia. Połącz je z kompetencjami.',btn('Dodaj sesję','add-session','primary','plus'))+
 `<div class="course-band"><div><div class="eyebrow">Szkoła Trenerów PZPN</div><h2>${esc(c.name)}</h2><p>${esc(c.location||'Uzupełnij miejsce kursu w ustawieniach')}</p></div><span class="edition-badge">${esc(c.edition||'Twój kurs')}</span></div>`+
 `<div class="metrics">${metric('Sesje kursu',c.sessions.length,`${allDays} dni w harmonogramie`,'calendar')}${metric('Czas zajęć',fmt(total),'Bez przerw','clock')}${metric('Zajęcia',ls.length,'W całym kursie','book')}${metric('Przypisane kompetencje',`${tagged}<small> / ${ls.length} zajęć</small>`,`${c.competencies.length} kompetencji w modelu`,'grid')}</div>`+
 `<div class="workspace">${!s?empty('Zacznij od pierwszej sesji','Dodaj zjazd, a następnie dni i zajęcia kursu.',btn('Dodaj sesję','add-session','primary','plus')):`<div class="session-bar"><div class="session-picker"><div class="session-mark">${icon('layers')}</div><div><select id="session-select" aria-label="Wybierz sesję">${c.sessions.map(x=>`<option value="${esc(x.id)}" ${x.id===s.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><span class="session-location">${esc(s.location||'Miejsce do uzupełnienia')}</span></div>${iconButton('edit','edit-session',s.id,'Edytuj sesję')}</div>${btn('Drukuj dzień','print','small','print')}</div><div class="days-bar"><div class="day-tabs" role="tablist" aria-label="Dni sesji">${s.days.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(x=>`<button class="day-tab ${d?.id===x.id?'active':''}" data-action="select-day" data-id="${x.id}" role="tab" aria-selected="${d?.id===x.id}"><strong>${df(x.date,{weekday:'long'})}${M.conflicts(x).size?'<span class="warning-dot" title="Nakładające się godziny">!</span>':''}</strong>${df(x.date,{day:'2-digit',month:'long'})}</button>`).join('')}</div>${btn('Dodaj dzień','add-day','ghost small day-add','plus')}</div>${d?renderDay(d,s):empty('Sesja czeka na pierwszy dzień','Wybierz datę, aby rozpocząć układanie harmonogramu.',btn('Dodaj dzień','add-day','primary','plus'))}`}</div><div class="section-bottom"><span>${icon('info')} Czas zajęć wyliczany z godzin rozpoczęcia i zakończenia.</span><span>1 godzina lekcyjna = 45 minut</span></div>`;
}
function renderDay(d,s){const entries=d.entries.slice().sort((a,b)=>M.mins(a.start)-M.mins(b.start)),conflicts=M.conflicts(d),ls=entries.filter(e=>e.type==='lesson'),sum=ls.reduce((n,e)=>n+M.duration(e),0);
 return `<div class="print-only print-heading"><img src="logo-pzpn.png" alt="Szkoła Trenerów PZPN"><h1>${esc(course().name)} · ${esc(course().edition)}</h1><p>${esc(s.name)} · ${esc(course().location)}</p></div><div class="schedule-heading"><div><h3>${fullDate(d.date)}</h3><p>${ls.length} zajęć · ${fmt(sum)} · ${(sum/45).toLocaleString('pl-PL',{maximumFractionDigits:2})} godz. lekcyjnych</p></div><div class="actions">${iconButton('edit','edit-day',d.id,'Edytuj dzień')}${btn('Przerwa','add-break','small','coffee')}${btn('Dodaj zajęcia','add-entry','small primary','plus')}</div></div>${conflicts.size?`<div class="notice">${icon('alert')}<span><strong>Nakładające się godziny.</strong> Sprawdź ${conflicts.size} oznaczone pozycje w tym dniu.</span></div>`:''}${!entries.length?empty('Miejsce na dobry plan','Dodaj pierwszy wykład, warsztat lub zajęcia na boisku.',btn('Dodaj zajęcia','add-entry','primary','plus')):`<table class="schedule-table"><thead><tr><th>Godziny</th><th>Temat i kompetencje</th><th>Prowadzący</th><th>Forma i miejsce</th><th><span class="sr-only"> </span></th></tr></thead><tbody>${entries.map(e=>e.type==='break'?`<tr class="break-row ${conflicts.has(e.id)?'conflict-row':''}"><td>${esc(e.start)}–${esc(e.end)}</td><td colspan="3"><div class="break-content">${icon('coffee')}<span>${esc(e.title)}</span><span>· ${M.duration(e)} min${conflicts.has(e.id)?' · konflikt godzin':''}</span></div></td><td>${iconButton('edit','edit-entry',e.id,'Edytuj przerwę')}</td></tr>`:`<tr class="${conflicts.has(e.id)?'conflict-row':''}"><td><div class="time-main">${e.start}</div><div class="time-end">${e.end}</div><span class="duration">${M.duration(e)} min</span>${conflicts.has(e.id)?'<div class="conflict-label">Konflikt godzin</div>':''}</td><td><button class="title-btn" data-action="edit-entry" data-id="${e.id}">${esc(e.title)}</button><div class="tags">${e.competencyIds.map(id=>course().competencies.find(k=>k.id===id)).filter(Boolean).map(tag).join('')}<button class="tag-add" data-action="tag-entry" data-id="${e.id}">${icon('plus')}${e.competencyIds.length?'Zmień':'Przypisz kompetencje'}</button></div>${e.note?`<p class="row-note">${esc(e.note)}</p>`:''}</td><td><div class="trainer">${esc(e.trainer||'—')}</div></td><td><div class="method">${esc(e.method||'—')}</div><div class="meta-line">${icon('pin')}${esc(e.location||'—')}</div></td><td>${iconButton('edit','edit-entry',e.id,'Edytuj zajęcia')}</td></tr>`).join('')}</tbody></table>`}<div class="schedule-footer">${icon('grid')}Kompetencje przypisane w ${ls.filter(e=>e.competencyIds.length).length} z ${ls.length} zajęć tego dnia.</div>`;
}
function renderCompetencies(){const stats=M.analytics(course()).stats;
 return heading('Model kompetencyjny','Kompetencje, które rozwijasz w trakcie kursu.',btn('Dodaj kompetencję','add-competency','primary','plus'))+
 `<div class="competency-toolbar"><div class="search">${icon('search')}<input id="competency-search" type="search" value="${esc(competencyFilter)}" placeholder="Szukaj kompetencji…" aria-label="Szukaj kompetencji"></div><div class="group-tabs" aria-label="Obszar kompetencji">${['Wszystkie',...M.GROUPS].map(g=>`<button data-action="filter-group" data-id="${g}" class="${g===groupFilter?'active':''}" aria-pressed="${g===groupFilter}">${g}</button>`).join('')}</div></div><div id="competency-list">${competencyCards(stats)}</div><p class="small-note">Model na podstawie przesłanego schematu. Nazwy, opisy i przypisanie do obszarów możesz edytować.</p>`;
}
function competencyCards(stats){const filtered=stats.filter(k=>(groupFilter==='Wszystkie'||groupFilter===k.group)&&k.name.toLocaleLowerCase('pl').includes(competencyFilter.toLocaleLowerCase('pl')));if(!filtered.length)return `<div class="workspace">${empty('Brak kompetencji','Dodaj kompetencję lub zmień kryteria wyszukiwania.',btn('Dodaj kompetencję','add-competency','primary','plus'),'grid')}</div>`;
 return `<div class="competency-grid">${M.GROUPS.filter(g=>filtered.some(k=>k.group===g)).map((g,i)=>`<section class="group-panel"><div class="group-panel-title"><span class="group-number">0${M.GROUPS.indexOf(g)+1}</span><div><h2>${g}</h2><p>${stats.filter(k=>k.group===g).length} kompetencji</p></div></div>${filtered.filter(k=>k.group===g).map(k=>`<article class="competency-card"><div class="competency-card-top"><h3>${esc(k.name)}</h3>${iconButton('edit','edit-competency',k.id,'Edytuj kompetencję: '+k.name)}</div>${k.description?`<p>${esc(k.description)}</p>`:''}<div class="competency-usage"><span>${k.count} zajęć</span><span>${fmt(k.minutes)}</span></div></article>`).join('')}</section>`).join('')}</div>`;
}
function renderAnalytics(){const a=M.analytics(course()),covered=a.stats.filter(k=>k.count>0).length,pct=a.stats.length?Math.round(covered/a.stats.length*100):0,sorted=[...a.stats].sort((a,b)=>b[chartMode]-a[chartMode]||a.name.localeCompare(b.name,'pl')),max=Math.max(1,...sorted.map(k=>k[chartMode]));
 return heading('Analityka kursu','Sprawdź, jak program zajęć pokrywa model kompetencyjny.','',esc(course().name))+
 `<div class="metrics">${metric('Czas całego kursu',fmt(a.total),'Zajęcia bez przerw','clock')}${metric('Zajęcia w programie',a.lessonCount,`${course().sessions.length} sesji kursu`,'book')}${metric('Rozwijane kompetencje',`${covered}<small> / ${a.stats.length}</small>`,'Z co najmniej jednymi zajęciami','grid')}${metric('Bez kompetencji',a.lessonCount-a.tagged,'Zajęcia do uzupełnienia','layers')}</div>${a.tagged===0?`<div class="notice neutral" style="margin-left:0;margin-right:0">${icon('info')}<span>Przypisz kompetencje do zajęć w harmonogramie. Wykresy i kombinacje uzupełnią się automatycznie.</span></div>`:''}
 <div class="analytics-layout"><section class="panel"><div class="panel-header"><div><h2>Pokrycie kompetencji</h2><p>${chartMode==='minutes'?'Czas zajęć przypisany do każdej kompetencji':'Liczba zajęć przypisanych do każdej kompetencji'}</p></div><div class="group-tabs"><button data-action="chart-mode" data-id="minutes" class="${chartMode==='minutes'?'active':''}" aria-pressed="${chartMode==='minutes'}">Czas</button><button data-action="chart-mode" data-id="count" class="${chartMode==='count'?'active':''}" aria-pressed="${chartMode==='count'}">Zajęcia</button></div></div><div class="chart-axis"><span>KOMPETENCJA</span><div class="ticks"><span>0</span><span>${chartMode==='minutes'?fmt(max===1?0:max):max===1&&!a.tagged?0:max}</span></div><span></span></div>${sorted.map(k=>`<div class="bar-row"><div class="bar-name"><i class="group-dot ${k.group==='Środowisko'?'env':k.group==='Drużyna'?'team':''}"></i>${esc(k.name)}</div><div class="bar-track" aria-hidden="true"><div class="bar-fill ${k.group==='Środowisko'?'env':k.group==='Drużyna'?'team':''}" style="width:${k[chartMode]/max*100}%"></div></div><div class="bar-value">${chartMode==='minutes'?fmt(k.minutes):k.count}</div></div>`).join('')||'<p class="small-note">Dodaj kompetencje do modelu kursu.</p>'}<div class="legend"><span><i class="group-dot"></i>Ja</span><span><i class="group-dot env"></i>Środowisko</span><span><i class="group-dot team"></i>Drużyna</span></div></section>
 <div class="analytics-side"><section class="panel"><h2>Kompletność programu</h2><div class="coverage-top"><div class="ring" style="--value:${pct}"><div class="ring-inner">${pct}%<small>kompetencji</small></div></div><div class="coverage-text"><strong>${covered} z ${a.stats.length}</strong>kompetencji ma zajęcia<br>w harmonogramie</div></div><div class="mini-stat"><span>Zajęcia z kompetencjami</span><b>${a.tagged} / ${a.lessonCount}</b></div><div class="progress-line"><i style="width:${a.lessonCount?a.tagged/a.lessonCount*100:0}%"></i></div><p class="small-note">Pokrycie pokazuje obecność kompetencji w programie. Nie jest oceną poziomu opanowania jej przez uczestników.</p></section><section class="panel"><div class="panel-header"><div><h2>Wspólnie na zajęciach</h2><p>Najczęstsze kombinacje kompetencji</p></div></div><div class="group-tabs"><button data-action="combo-mode" data-id="pairs" class="${comboMode==='pairs'?'active':''}">Pary</button><button data-action="combo-mode" data-id="sets" class="${comboMode==='sets'?'active':''}">Pełne zestawy</button></div>${a[comboMode].length?a[comboMode].slice(0,8).map((x,i)=>`<div class="combination"><div class="combination-top"><span>0${i+1}</span><span><b>${x.count} zajęć</b> · ${fmt(x.minutes)}</span></div><div class="tags">${x.ids.map(id=>course().competencies.find(k=>k.id===id)).map(tag).join('')}</div></div>`).join(''):`<div class="empty" style="padding:28px 0 5px"><p>Brak kombinacji. Wybierz co najmniej dwie kompetencje dla jednych zajęć.</p></div>`}<p class="small-note">${comboMode==='pairs'?'Para jest liczona także wtedy, gdy zajęcia mają więcej niż dwie kompetencje.':'Zestaw obejmuje dokładnie wszystkie kompetencje przypisane do jednych zajęć.'}</p></section></div></div>
 <div class="panel" style="margin-top:20px"><h2>Zestawienie kompetencji</h2><div class="details-table"><table class="data-table"><thead><tr><th>Kompetencja</th><th>Obszar</th><th>Zajęcia</th><th>Czas</th><th>Godz. lekcyjne</th></tr></thead><tbody>${a.stats.map(k=>`<tr><td>${esc(k.name)}</td><td>${k.group}</td><td>${k.count}</td><td>${fmt(k.minutes)}</td><td>${(k.minutes/45).toLocaleString('pl-PL',{maximumFractionDigits:2})}</td></tr>`).join('')}</tbody></table></div><p class="small-note">Pełny czas zajęć jest przypisywany każdej wybranej kompetencji. Suma czasów kompetencji może przekraczać czas kursu. Przerwy nie są uwzględniane. Dane obejmują cały zaplanowany program.</p></div>`;
}
function renderSettings(){const c=course();return heading('Ustawienia kursu','Dane kursu i bezpieczne przenoszenie harmonogramu.')+`<div class="settings-grid"><section class="panel settings-card"><div class="settings-card-header">${icon('book')}<h2>Informacje o kursie</h2></div><form id="course-form"><div class="form-grid"><div class="field full"><label for="course-name">Nazwa kursu</label><input id="course-name" name="name" value="${esc(c.name)}" required maxlength="200"></div><div class="field full"><label for="course-edition">Edycja</label><input id="course-edition" name="edition" value="${esc(c.edition)}" maxlength="200" placeholder="Np. Edycja 2 · 2026"></div><div class="field full"><label for="course-location">Miejsce kursu</label><textarea id="course-location" name="location" maxlength="1000">${esc(c.location)}</textarea></div></div><div class="settings-actions"><button class="btn primary" type="submit">${icon('check')}Zapisz informacje</button></div></form></section><div class="settings-stack"><section class="panel settings-card"><div class="settings-card-header">${icon('download')}<h2>Eksport kursu</h2></div><p>Pobierz wszystkie sesje, dni, zajęcia i kompetencje w jednym pliku JSON.</p>${btn('Eksportuj kurs do JSON','export','','download')}</section><section class="panel settings-card"><div class="settings-card-header">${icon('upload')}<h2>Import kursu</h2></div><p>Wczytaj wcześniej wyeksportowany plik. Import zastąpi cały aktualny kurs po Twoim potwierdzeniu.</p><label class="file-label" for="import-file">Plik kursu (.json)</label><input class="file-input" id="import-file" type="file" accept=".json,application/json"><div id="import-result"></div></section><section class="panel settings-card"><div class="settings-card-header">${icon('save')}<h2>Zapis w przeglądarce</h2></div><p>Zmiany zapisują się automatycznie na tym urządzeniu, w tej przeglądarce. Aby przenieść kurs lub wykonać kopię, użyj eksportu JSON.</p><div class="small-note">Wyczyszczenie danych przeglądarki usuwa zapis lokalny. Nie ma synchronizacji między urządzeniami.</div></section></div></div>`;}
function showModal(title,body,submitText,fn,{deleteAction='',deleteId='',wide=false}={}){const m=$('#modal');lastFocus=document.activeElement;modalSubmit=fn;m.innerHTML=`<form id="modal-form"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="icon-btn" data-action="close-modal" aria-label="Zamknij">${icon('x')}</button></div><div class="modal-body">${body}<div id="modal-error" class="modal-error" role="alert"></div></div><div class="modal-footer">${deleteAction?btn('Usuń',deleteAction,'danger delete','trash',deleteId):''}${btn('Anuluj','close-modal')}${submitText?`<button type="submit" class="btn primary">${submitText}</button>`:''}</div></form>`;if(!m.open)m.showModal();}
function closeModal(){const m=$('#modal');m.close();modalSubmit=null;if(lastFocus?.isConnected)lastFocus.focus();}
function errorModal(message){$('#modal-error').textContent=message;}
function confirmAction(title,copy,fn,label='Usuń'){showModal(title,`<p class="confirm-copy">${copy}</p>`,label,()=>{fn();closeModal();render();});}
function formValue(fd,name){return String(fd.get(name)??'').trim();}
function sessionModal(edit=false){const s=edit?session():null;showModal(s?'Edytuj sesję':'Nowa sesja',`<div class="form-grid"><div class="field full"><label for="session-name">Nazwa sesji</label><input id="session-name" name="name" required maxlength="200" value="${esc(s?.name||'Sesja '+(Math.max(0,...course().sessions.map(s=>Number(s.name.match(/\d+/)?.[0])||0))+1))}"></div><div class="field full"><label for="session-location">Miejsce sesji</label><input id="session-location" name="location" maxlength="1000" value="${esc(s?.location||'')}"></div></div>`,s?'Zapisz zmiany':'Dodaj sesję',fd=>{const name=formValue(fd,'name');if(!name)return errorModal('Podaj nazwę sesji.');if(s){s.name=name;s.location=formValue(fd,'location');}else{const x={id:M.uid(),name,location:formValue(fd,'location'),days:[]};course().sessions.push(x);data.ui.sessionId=x.id;data.ui.dayId=null;}save(s?'Zapisano sesję':'Dodano sesję');closeModal();render();},{deleteAction:s?'delete-session':'',deleteId:s?.id});}
function nextDate(value){const x=new Date(value+'T12:00:00Z');x.setUTCDate(x.getUTCDate()+1);return x.toISOString().slice(0,10);}
function dayModal(edit=false){const s=session();if(!s)return;const d=edit?day():null;const dates=s.days.map(x=>x.date).sort();showModal(d?'Edytuj dzień':'Nowy dzień sesji',`<div class="field"><label for="day-date">Data</label><input id="day-date" type="date" name="date" required value="${d?.date||(dates.length?nextDate(dates.at(-1)):today())}"></div>`,d?'Zapisz zmiany':'Dodaj dzień',fd=>{const date=formValue(fd,'date');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(new Date(date+'T12:00:00Z').valueOf()))return errorModal('Wybierz poprawną datę.');if(s.days.some(x=>x.id!==d?.id&&x.date===date))return errorModal('Ta sesja ma już dzień z wybraną datą.');if(d)d.date=date;else{const x={id:M.uid(),date,entries:[]};s.days.push(x);data.ui.dayId=x.id;}save(d?'Zapisano dzień':'Dodano dzień');closeModal();render();},{deleteAction:d?'delete-day':'',deleteId:d?.id});}
function pickerHtml(selected){return `<div class="field full"><label>Kompetencje</label><details class="picker" id="competency-picker"><summary><span id="picker-label">Wybierz kompetencje (${selected.size})</span>${icon('chevron')}</summary><div class="picker-body"><input id="picker-search" type="search" placeholder="Szukaj na liście…" aria-label="Wyszukaj kompetencję">${M.GROUPS.map(g=>`<div class="picker-group">${g}</div>${course().competencies.filter(k=>k.group===g).map(k=>`<label class="check-option" data-name="${esc(k.name.toLocaleLowerCase('pl'))}"><input type="checkbox" name="competency" value="${k.id}" ${selected.has(k.id)?'checked':''}>${esc(k.name)}</label>`).join('')}`).join('')}${course().competencies.length?'':'<p class="helper">Najpierw dodaj kompetencje w zakładce Kompetencje.</p>'}<p id="picker-empty" class="helper" hidden>Brak pasujących kompetencji.</p></div></details><div class="tags selected-tags" id="selected-tags"></div><small>Możesz wybrać dowolną liczbę kompetencji.</small></div>`;}
function bindPicker(selected){function update(){const label=$('#picker-label');if(!label)return;label.textContent=`Wybierz kompetencje (${selected.size})`;$('#selected-tags').innerHTML=[...selected].map(id=>course().competencies.find(k=>k.id===id)).filter(Boolean).map(k=>`<span class="tag ${k.group==='Ja'?'self':k.group==='Drużyna'?'team':''}">${esc(k.name)}<button type="button" data-remove-competency="${k.id}" aria-label="Odznacz ${esc(k.name)}">${icon('x')}</button></span>`).join('');}
 $('#competency-picker').addEventListener('change',e=>{if(e.target.name==='competency'){if(e.target.checked)selected.add(e.target.value);else selected.delete(e.target.value);update();}});
 $('#selected-tags').addEventListener('click',e=>{const b=e.target.closest('[data-remove-competency]');if(!b)return;selected.delete(b.dataset.removeCompetency);document.querySelectorAll('input[name="competency"]').forEach(x=>{x.checked=selected.has(x.value);});update();});
 $('#picker-search').addEventListener('input',e=>{const value=e.target.value.toLocaleLowerCase('pl');let count=0;document.querySelectorAll('.check-option').forEach(el=>{el.hidden=!el.dataset.name.includes(value);if(!el.hidden)count++;});$('#picker-empty').hidden=count>0;});update();}
function entryModal(id=null,type='lesson',openPicker=false){const d=day();if(!d)return;const existing=d.entries.find(x=>x.id===id);if(existing)type=existing.type;const isBreak=type==='break';let start=existing?.start||d.entries.slice().sort((a,b)=>M.mins(a.end)-M.mins(b.end)).at(-1)?.end||'09:00';if(M.mins(start)>1424)start='09:00';const endMinutes=Math.min(1439,M.mins(start)+(isBreak?20:90));const end=existing?.end||String(Math.floor(endMinutes/60)).padStart(2,'0')+':'+String(endMinutes%60).padStart(2,'0');const selected=new Set(existing?.competencyIds||[]);
 const trainerNames=[...new Set(M.lessons(course()).map(e=>e.trainer).filter(Boolean))];
 showModal(existing?(isBreak?'Edytuj przerwę':'Edytuj zajęcia'):(isBreak?'Dodaj przerwę':'Dodaj zajęcia'),`<div class="form-grid"><div class="field full"><label for="entry-title">${isBreak?'Nazwa przerwy':'Temat zajęć'}</label><textarea id="entry-title" name="title" required maxlength="2000" rows="2">${esc(existing?.title||(isBreak?'Przerwa':''))}</textarea></div><div class="field"><label for="entry-start">Rozpoczęcie</label><input id="entry-start" name="start" type="time" value="${start}" required></div><div class="field"><label for="entry-end">Zakończenie</label><input id="entry-end" name="end" type="time" value="${end}" required></div><div class="field full"><div class="computed-duration"><span>Czas trwania</span><strong id="entry-duration"></strong></div><div id="overlap-hint" class="helper"></div></div>${!isBreak?`<div class="field full"><label for="entry-trainer">Prowadzący</label><input id="entry-trainer" name="trainer" list="trainers" value="${esc(existing?.trainer||'')}" maxlength="1000" placeholder="Imię i nazwisko"><datalist id="trainers">${trainerNames.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></div><div class="field mobile-stack"><label for="entry-method">Metoda</label><input id="entry-method" name="method" list="methods" maxlength="300" value="${esc(existing?.method||'Warsztaty')}"><datalist id="methods">${['Prezentacja / Warsztaty','Warsztaty','Praktyka','Dyskusja','Wykład'].map(x=>`<option value="${x}">`).join('')}</datalist></div><div class="field mobile-stack"><label for="entry-location">Miejsce</label><input id="entry-location" name="location" list="locations" maxlength="1000" value="${esc(existing?.location||'Sala wykładowa')}"><datalist id="locations"><option value="Sala wykładowa"><option value="Boisko"></datalist></div>${pickerHtml(selected)}`:''}<div class="field full"><label for="entry-note">Notatka <span class="subtext">(opcjonalnie)</span></label><textarea id="entry-note" name="note" maxlength="3000" rows="2">${esc(existing?.note||'')}</textarea></div></div>`,existing?'Zapisz zmiany':isBreak?'Dodaj przerwę':'Dodaj zajęcia',fd=>{const st=formValue(fd,'start'),en=formValue(fd,'end'),title=formValue(fd,'title');if(!title)return errorModal('Podaj temat lub nazwę.');if(!st||!en||M.mins(en)<=M.mins(st))return errorModal('Zakończenie musi być późniejsze niż rozpoczęcie, w tym samym dniu.');const entry={id:existing?.id||M.uid(),type,start:st,end:en,title,trainer:isBreak?'':formValue(fd,'trainer'),method:isBreak?'':formValue(fd,'method'),location:isBreak?'':formValue(fd,'location'),note:formValue(fd,'note'),competencyIds:isBreak?[]:[...selected]};if(existing)Object.assign(existing,entry);else d.entries.push(entry);save('Zapisano '+(isBreak?'przerwę':'zajęcia'));closeModal();render();},{deleteAction:existing?'delete-entry':'',deleteId:existing?.id});
 function updateTime(){const st=$('#entry-start').value,en=$('#entry-end').value,n=st&&en?M.mins(en)-M.mins(st):0;$('#entry-duration').textContent=n>0?`${n} min${!isBreak?' · '+(n/45).toLocaleString('pl-PL',{maximumFractionDigits:2})+' godz. lekcyjnych':''}`:'Sprawdź godziny';const overlaps=d.entries.filter(e=>e.id!==existing?.id&&n>0&&M.mins(st)<M.mins(e.end)&&M.mins(e.start)<M.mins(en));$('#overlap-hint').textContent=overlaps.length?'Uwaga: te godziny nakładają się na '+overlaps.length+' inne pozycje. Możesz zapisać je i poprawić później.':'';}
 $('#entry-start').addEventListener('input',updateTime);$('#entry-end').addEventListener('input',updateTime);updateTime();if(!isBreak){bindPicker(selected);if(openPicker){$('#competency-picker').open=true;$('#picker-search').focus();}}}
function competencyModal(id=null){const k=course().competencies.find(x=>x.id===id);showModal(k?'Edytuj kompetencję':'Nowa kompetencja',`<div class="form-grid"><div class="field full"><label for="competency-name">Nazwa kompetencji</label><input id="competency-name" name="name" required maxlength="200" value="${esc(k?.name||'')}"></div><div class="field full"><label for="competency-group">Obszar modelu</label><select id="competency-group" name="group">${M.GROUPS.map(g=>`<option ${k?.group===g?'selected':''}>${g}</option>`).join('')}</select></div><div class="field full"><label for="competency-description">Opis <span class="subtext">(opcjonalnie)</span></label><textarea id="competency-description" name="description" maxlength="3000">${esc(k?.description||'')}</textarea></div></div>`,k?'Zapisz zmiany':'Dodaj kompetencję',fd=>{const name=formValue(fd,'name');if(!name)return errorModal('Podaj nazwę kompetencji.');if(course().competencies.some(x=>x.id!==k?.id&&x.name.toLocaleLowerCase('pl')===name.toLocaleLowerCase('pl')))return errorModal('Kompetencja o tej nazwie już istnieje.');const item={id:k?.id||M.uid(),name,group:formValue(fd,'group'),description:formValue(fd,'description')};if(k)Object.assign(k,item);else course().competencies.push(item);save('Zapisano kompetencję');closeModal();render();},{deleteAction:k?'delete-competency':'',deleteId:k?.id});}
function exportCourse(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='kurs-'+course().name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-')+'-'+today()+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Wyeksportowano kurs do JSON');}
function bindImport(){pendingImport=null;let fileRead=0;$('#import-file').addEventListener('change',async e=>{const request=++fileRead;pendingImport=null;const out=$('#import-result'),file=e.target.files[0];out.innerHTML='';if(!file)return;try{if(file.size>10*1024*1024)throw new Error('Plik przekracza 10 MB.');const raw=JSON.parse(await file.text());const parsed=M.validate(raw);if(request!==fileRead||!out.isConnected)return;pendingImport=parsed;const a=M.analytics(parsed.course);out.innerHTML=`<div class="import-preview"><h3>${esc(parsed.course.name)}</h3><p>${parsed.course.sessions.length} sesji · ${a.lessonCount} zajęć · ${parsed.course.competencies.length} kompetencji</p><p>Plik jest poprawny. Aktualny kurs zostanie zastąpiony.</p>${btn('Importuj i zastąp kurs','confirm-import','primary small','upload')}</div>`;}catch(err){if(request!==fileRead||!out.isConnected)return;out.innerHTML=`<div class="validation-error" role="alert">${esc(err instanceof SyntaxError?'Nie można odczytać pliku JSON. Wybierz poprawny eksport kursu.':err.message)} Aktualny kurs pozostaje bez zmian.</div>`;}});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id,a=b.dataset.action;
 if(a==='view'){data.ui.view=id;save();render();window.scrollTo({top:0});}
 else if(a==='select-day'){data.ui.dayId=id;save();render();}
 else if(a==='add-session')sessionModal();else if(a==='edit-session')sessionModal(true);
 else if(a==='add-day')dayModal();else if(a==='edit-day')dayModal(true);
 else if(a==='add-entry')entryModal();else if(a==='add-break')entryModal(null,'break');else if(a==='edit-entry')entryModal(id);else if(a==='tag-entry')entryModal(id,'lesson',true);
 else if(a==='add-competency')competencyModal();else if(a==='edit-competency')competencyModal(id);
 else if(a==='close-modal')closeModal();
 else if(a==='delete-entry'){const d=day(),item=d.entries.find(x=>x.id===id);if(item)confirmAction('Usunąć pozycję?',`„${esc(item.title)}” zostanie usunięte z tego dnia.`,()=>{d.entries=d.entries.filter(x=>x.id!==id);save('Usunięto pozycję');});}
 else if(a==='delete-day'){const s=session(),d=s.days.find(x=>x.id===id);if(d)confirmAction('Usunąć dzień?',`Dzień <strong>${esc(fullDate(d.date))}</strong> i wszystkie jego pozycje (${d.entries.length}) zostaną usunięte.`,()=>{s.days=s.days.filter(x=>x.id!==id);data.ui.dayId=null;save('Usunięto dzień');});}
 else if(a==='delete-session'){const s=course().sessions.find(x=>x.id===id);if(s)confirmAction('Usunąć sesję?',`<strong>${esc(s.name)}</strong> i wszystkie jej dni (${s.days.length}) oraz zajęcia zostaną usunięte.`,()=>{course().sessions=course().sessions.filter(x=>x.id!==id);data.ui.sessionId=null;data.ui.dayId=null;save('Usunięto sesję');});}
 else if(a==='delete-competency'){const k=course().competencies.find(x=>x.id===id),count=M.lessons(course()).filter(x=>x.competencyIds.includes(id)).length;if(k)confirmAction('Usunąć kompetencję?',`<strong>${esc(k.name)}</strong> zostanie usunięta z modelu oraz odpięta od ${count} zajęć. Same zajęcia pozostaną w harmonogramie.`,()=>{course().competencies=course().competencies.filter(x=>x.id!==id);course().sessions.forEach(s=>s.days.forEach(d=>d.entries.forEach(e=>e.competencyIds=e.competencyIds.filter(x=>x!==id))));save('Usunięto kompetencję');});}
 else if(a==='filter-group'){groupFilter=id;render();}else if(a==='chart-mode'){chartMode=id;render();}else if(a==='combo-mode'){comboMode=id;render();}
 else if(a==='export')exportCourse();else if(a==='print'){if(day())window.print();else toast('Dodaj najpierw dzień do sesji.');}
 else if(a==='confirm-import'&&pendingImport){const incoming=pendingImport;confirmAction('Zastąpić aktualny kurs?',`Import kursu <strong>${esc(incoming.course.name)}</strong> zastąpi wszystkie dane kursu <strong>${esc(course().name)}</strong>. Tej operacji nie można cofnąć. Przed importem możesz wyeksportować aktualny kurs.`,()=>{data=incoming;data.ui.view='schedule';protectStorage=false;pendingImport=null;save('Zaimportowano kurs');},'Zastąp kurs');}
});
document.addEventListener('change',e=>{if(e.target.id==='session-select'){data.ui.sessionId=e.target.value;data.ui.dayId=null;save();render();}});
document.addEventListener('input',e=>{if(e.target.id==='competency-search'){competencyFilter=e.target.value;$('#competency-list').innerHTML=competencyCards(M.analytics(course()).stats);}});
document.addEventListener('submit',e=>{if(e.target.id==='modal-form'){e.preventDefault();modalSubmit?.(new FormData(e.target));}else if(e.target.id==='course-form'){e.preventDefault();const fd=new FormData(e.target),name=formValue(fd,'name');if(!name){toast('Podaj nazwę kursu');return;}course().name=name;course().edition=formValue(fd,'edition');course().location=formValue(fd,'location');save('Zapisano informacje o kursie');render();}});
window.addEventListener('storage',e=>{if(e.key===M.KEY&&e.newValue){try{const incoming=M.validate(JSON.parse(e.newValue));if($('#modal').open){toast('Kurs zmienił się w innej karcie. Zapis tego formularza zastąpi te zmiany.');return;}data=incoming;render();toast('Wczytano zmiany z innej karty');}catch(err){toast('Nie udało się odczytać zmian z innej karty.');}}});
render();
